INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 1, 'theory', 'How a Network Works: Nodes, Links, and Packets');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 0, 'What is the advantage of packet switching over circuit switching?', '["A circuit is reserved for each user forever", "While one node is silent, others use the freed capacity", "Packets are never lost", "Delay is always zero"]', 1, 'Statistical multiplexing: packets of different users share the link and fill each other''s pauses.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 1, 'What terms make up the delay of a packet on one hop?', '["Only the transmission time", "The speed of light and the number of hosts", "Processing, queueing, transmission, and propagation", "The header size and the length of the node''s name"]', 2, 'Four components: header processing, waiting in the queue, transmission L/R, and signal propagation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 2, 'How many seconds does it take to transmit a packet of L bits over a link of R bit/s?', '["L / R", "L · R", "R / L", "L + R"]', 0, 'Transmission time is the packet size divided by the link speed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 3, 'What does a router do when its buffer is completely full?', '["Raises the link speed", "Postpones the packet for an hour", "Compresses all the packets in the queue", "Drops new packets"]', 3, 'The buffer is finite; a loss is a normal way of telling the sender "slow down".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 1, 4, 'What is the BDP, the bandwidth-delay product?', '["The number of hosts in a network", "The number of bits in the link at the same moment", "The maximum size of an Ethernet frame", "The variation of delay between packets"]', 1, 'It is the capacity of the link: that many bits are in flight at once; if you send less, the link sits idle.');
